//! The native EMITTER arm's own integration tests (`cargo test`), run with
//! no Python on the machine. GENERATED by `tools/build_gate_crate.py`.
//!
//! Roadmap item 146 condition 4: `selfhost/emit_rust.rvl` is generated into this
//! crate, so a caller with a reference-produced interchange IR document can emit
//! rust natively. The claim that matters is BYTE AGREEMENT with the reference
//! rust backend, and a byte comparison is only evidence if the expectation comes
//! from the reference rather than from the thing under test.
//!
//! So both sides of the comparison below are DERIVED at generation time: the IR
//! document is `revl.compiler.compile_source` on the probe, and the expected rust
//! is `backends/rust/emit.py` on that document. Neither is transcribed. A change
//! to the frontend or the backend rewrites this file, which reds
//! `tests/test_gate_crate_drift.py` in the same wave.
//!
//! This runs the comparison with NO PYTHON PRESENT, which is the half
//! `tests/test_gate_crate_admit.py` cannot show from inside a pytest process.

/// The probe source, for the record: fn id(x: Int) -> Int { return x }
/// The staged interchange IR the REFERENCE frontend produced for it.
const PROBE_IR: &str = r####"{"ir_version": 3, "services": {}, "components": [], "manifest": {"components": [], "loadOrder": []}, "functions": [{"name": "id", "params": [{"name": "x", "type": "Int"}], "returns": "Int", "public": false, "body": [{"step": "return", "expr": {"kind": "var", "name": "x"}}]}]}"####;

/// What the REFERENCE rust backend emitted from that document.
const PROBE_WANT: &str = r####"//! Generated by the revl cordis-rs backend (ir_version 3): do not edit.
//! Target: cordis-rs 0.6.x (docs.rs/cordis-rs).
#![allow(dead_code, unused_variables, unused_mut, unused_imports, unused_parens, unreachable_patterns)]

use std::sync::Arc;
use cordis::Value;

fn id(x: i64) -> i64 {
    return x;
}
"####;

#[test]
fn emit_ir_is_the_reference_rust_backend_byte_for_byte() {
    let got = revl_gate::emit_ir(PROBE_IR, revl_gate::Tier::Rust)
        .expect("the native emitter refused a reference-produced IR document");
    assert_eq!(got, PROBE_WANT,
               "the native emitter diverged from the reference rust backend");
}

#[test]
fn the_byte_comparison_can_fail() {
    // Non-vacuity. A comparison that cannot fail is not evidence, and the
    // expectation above is generated, so this is the cheapest way to show the
    // assertion has teeth rather than comparing a value with itself.
    let mut corrupted = String::from(PROBE_WANT);
    corrupted.push('X');
    let got = revl_gate::emit_ir(PROBE_IR, revl_gate::Tier::Rust).unwrap();
    assert_ne!(got, corrupted);
    assert!(!got.is_empty());
}

#[test]
fn the_py_tier_fails_closed() {
    // selfhost/emit_py.rvl's helper externs are @py-only, so no py emitter is in
    // this crate at all. It must refuse rather than fall back to the rust one.
    let refused = revl_gate::emit_ir(PROBE_IR, revl_gate::Tier::Py)
        .expect_err("emit_ir(py) must refuse: there is no py emitter in this crate");
    assert!(!refused.is_refused());
    assert!(refused.to_json().contains("\"admitted\":false"),
            "no arm of the emit surface may read as an admission: {}",
            refused.to_json());
}

#[test]
fn an_ir_document_the_boundary_refuses_is_never_emitted() {
    // The IR-boundary guard (item 479) runs AHEAD of the emitter: an unknown
    // top-level field is refused by name, not decoded under the wrong shape and
    // then emitted from.
    let unknown = "{\"ir_version\": 3, \"no_such_field\": 1}";
    let refused = revl_gate::emit_ir(unknown, revl_gate::Tier::Rust)
        .expect_err("a document carrying an unknown top-level field must be refused");
    match refused {
        revl_gate::Verdict::Refused { ref code, .. } => {
            assert_eq!(code, revl_gate::ir::IR_UNKNOWN_FIELD_CODE)
        }
        other => panic!("expected a named refusal, got {:?}", other),
    }
}

#[test]
fn a_document_that_is_not_json_is_refused_and_does_not_abort() {
    let refused = revl_gate::emit_ir("not json at all", revl_gate::Tier::Rust)
        .expect_err("a non-JSON document must be refused");
    match refused {
        revl_gate::Verdict::Refused { ref code, .. } => {
            assert_eq!(code, revl_gate::ir::IR_MALFORMED_CODE)
        }
        other => panic!("expected a named refusal, got {:?}", other),
    }
}

#[test]
fn a_document_over_the_size_bound_is_declined() {
    let over = "x".repeat(revl_gate::MAX_SOURCE_BYTES + 1);
    let declined = revl_gate::emit_ir(&over, revl_gate::Tier::Rust)
        .expect_err("a document over the size bound must be declined");
    assert!(matches!(declined, revl_gate::Verdict::OutsideFrontier { .. }));
}
